// Symbol table: model index <-> text. vocab.cpp is generated by tools/export_vocab.py.
#pragma once
#include <cstdint>

extern const char* const kVocab[];
extern const int kVocabSize;
// Padding symbol: fills the left part of the window when the text is shorter than the window.
// It is never generated. -1 if the vocabulary has none.
extern const int kVocabPadIndex;
// END-of-answer symbol: generation stops when the model emits it. -1 if there is none.
extern const int kVocabEndIndex;

// Index of the token equal to the whole string, or -1.
int VocabFind(const char* token);

// UTF-8 text -> indices (greedy, longest match). Unknown character -> unknown_index (skipped if < 0).
// Returns the number of indices written (at most max_out; the LAST symbols of the text are kept).
int VocabEncode(const char* text, uint16_t* out, int max_out, int unknown_index, int* n_unknown);
